window.__votdWeek && window.__votdWeek({"week":"2029-09-17","reading":"Doctrine and Covenants 102–105","days":[{"d":"2029-09-17","ref":"D&C 102:23","b":"D&C","c":102,"v":23,"he":"בְּמִקְרֶה קֹשִׁי הַנּוֹגֵעַ לְתוֹרָה אוֹ עִקָּר אִם אֵין דֵּי כָּתוּב לְבָאֵר הָעִנְיָן לְדַעַת הַסַּנְהֶדְרִין הַנָּשִׂיא יָכוֹל לִשְׁאֹל וּלְקַבֵּל אֶת־דַּעַת יְהוָה בְּחָזוֹן׃","en":"In case of difficulty respecting doctrine or principle, if there is not a sufficiency written to make the case clear to the minds of the council, the president may inquire and obtain the mind of the Lord by revelation."},{"d":"2029-09-18","ref":"D&C 103:9","b":"D&C","c":103,"v":9,"he":"כִּי הוּקְמוּ לִהְיוֹת אוֹר לָעוֹלָם וּמוֹשִׁיעֵי אֲנָשִׁים׃","en":"For they were set to be a light unto the world, and to be the saviors of men;"},{"d":"2029-09-19","ref":"D&C 103:16","b":"D&C","c":103,"v":16,"he":"לָכֵן אָקִים לְעַמִּי אִישׁ אֲשֶׁר יוֹלִיכֵם כַּאֲשֶׁר הוֹלִיךְ מֹשֶׁה בְּנֵי יִשְׂרָאֵל׃","en":"Therefore, I will raise up unto my people a man, who shall lead them like as Moses led the children of Israel."},{"d":"2029-09-20","ref":"D&C 104:16","b":"D&C","c":104,"v":16,"he":"אַךְ עָשֹׂה יֵעָשֶׂה בְּדַרְכִּי וְהִנֵּה זֹאת הַדֶּרֶךְ אֲשֶׁר גָּזַרְתִּי אֲנִי יְהוָה לְכַלְכֵּל קְדוֹשַׁי לְמַעַן יָרוּמוּ הָעֲנִיִּים בְּהַשְׁפָּלַת הָעֲשִׁירִים׃","en":"But it must needs be done in mine own way; and behold this is the way that I, the Lord, have decreed to provide for my saints, that the poor shall be exalted, in that the rich are made low."},{"d":"2029-09-21","ref":"D&C 104:18","b":"D&C","c":104,"v":18,"he":"לָכֵן אִם יִקַּח אִישׁ מֵהַשֶּׁפַע אֲשֶׁר עָשִׂיתִי וְלֹא יִתֵּן חֶלְקוֹ לְפִי תּוֹרַת בְּשׂוֹרָתִי לֶעָנִי וְלָאֶבְיוֹן יִשָּׂא עֵינָיו בִּשְׁאוֹל עִם הָרְשָׁעִים בְּיִסּוּרִים׃","en":"Therefore, if any man shall take of the abundance which I have made, and impart not his portion, according to the law of my gospel, unto the poor and the needy, he shall, with the wicked, lift up his eyes in hell, being in torment."},{"d":"2029-09-22","ref":"D&C 105:8","b":"D&C","c":105,"v":8,"he":"כִּי־אִם מְדַבֵּר עַל כְּנֵסִיּוֹתַי בַּמֶּרְחָקִים רַבִּים יֹאמְרוּ אַיֵּה אֱלֹהֵיהֶם הִנֵּה יַצִּילֵם בְּעֵת צָרָה וְאִם־לֹא לֹא נַעֲלֶה לְצִיּוֹן וְנִשְׁמֹר כַּסְפֵּנוּ׃","en":"But I speak concerning my churches abroad—there are many who will say: Where is their God? Behold, he will deliver them in time of trouble, otherwise we will not go up unto Zion, and will keep our moneys."},{"d":"2029-09-23","ref":"D&C 105:14","b":"D&C","c":105,"v":14,"he":"כִּי הִנֵּה אֵינֶנִּי דּוֹרֵשׁ מִיָּדָם לְהִלָּחֵם מִלְחֲמוֹת צִיּוֹן כִּי כַאֲשֶׁר אָמַרְתִּי בְּמִצְוָה קֹדֶמֶת כֵּן אֲקַיֵּם אֲנִי אֶלָּחֵם מִלְחֲמוֹתֵיכֶם׃","en":"For behold, I do not require at their hands to fight the battles of Zion; for, as I said in a former commandment, even so will I fulfil—I will fight your battles."}]});
